// --- MODERN APPROACH (Using Custom Hooks instead of Containers) ---
// This has largely replaced the Container/Presentational pattern.

// 1. The Logic (Extracted into a Custom Hook)
function useUserData(userId) {
  const [data, setData] = useState(null);
  useEffect(() => { fetchUser(userId).then(setData); }, [userId]);
  return data;
}

// 2. The Component (Cleanly handles both UI and calls the logic)
export default function UserProfile({ userId }) {
  const data = useUserData(userId);

  if (!data) return <p>Loading...</p>;
  return <div>{data.name}</div>;
}
